// Generates lib/src/pdfium_bindings.g.dart from the pinned PDFium headers.
//
// Run from the repository root after `tools/fetch_pdfium.sh linux`:
//   cd packages/pdfium_ffi && dart run tool/ffigen.dart
// Requires libclang (Arch: clang; Debian/Ubuntu: libclang-dev).

import 'dart:io';

import 'package:ffigen/ffigen.dart';

/// Public PDFium headers exposed to Dart. Add headers here when a feature
/// needs more of the API; never edit the generated file by hand.
const headers = [
  'fpdfview.h',
  'fpdf_annot.h',
  'fpdf_doc.h',
  'fpdf_edit.h',
  'fpdf_ext.h',
  'fpdf_formfill.h',
  'fpdf_ppo.h',
  'fpdf_progressive.h',
  'fpdf_save.h',
  'fpdf_signature.h',
  'fpdf_text.h',
  'fpdf_transformpage.h',
];

Future<void> main() async {
  final packageRoot = Platform.script.resolve('../');
  final includeDir = packageRoot.resolve('../../third_party/pdfium/include/');
  if (!File.fromUri(includeDir.resolve('fpdfview.h')).existsSync()) {
    stderr.writeln(
      'PDFium headers not found in ${includeDir.toFilePath()}.\n'
      'Run tools/fetch_pdfium.sh linux from the repository root first.',
    );
    exitCode = 1;
    return;
  }

  // libclang does not always find its own builtin headers (stddef.h, ...).
  // Pass the resource directory of the clang on PATH; unlike `-isystem`,
  // `-resource-dir` keeps the normal include order, so builtin headers that
  // use `#include_next` (stdint.h) still reach the system headers.
  final resourceDir = Process.runSync('clang', ['-print-resource-dir']);
  final builtinIncludes = [
    if (resourceDir.exitCode == 0) ...[
      '-resource-dir',
      (resourceDir.stdout as String).trim(),
    ],
  ];

  final generator = FfiGenerator(
    output: Output(
      dart: DartOutput(
        path: packageRoot.resolve('lib/src/pdfium_bindings.g.dart'),
      ),
      preamble: '''
// SPDX-License-Identifier: GPL-3.0-or-later
// Generated by packages/pdfium_ffi/tool/ffigen.dart from the PDFium headers
// pinned in tools/pdfium.lock. Do not edit by hand.
// ignore_for_file: type=lint, unused_field, unused_element''',
      style: const DynamicLibraryBindings(
        wrapperName: 'PdfiumBindings',
        wrapperDocComment: 'Raw bindings to the PDFium C API.',
      ),
    ),
    input: Input(
      entryPoints: [for (final h in headers) includeDir.resolve(h)],
      // Only bind declarations from PDFium's own headers, not system headers.
      include: (header) => header.path.startsWith(includeDir.path),
      compilerOptions: ['-I${includeDir.toFilePath()}', ...builtinIncludes],
      appendCompilerOptions: true,
    ),
    // Top-level declarations are excluded by default in ffigen 23+. The
    // header filter above already limits the input to PDFium, so include
    // every declaration found there.
    visitors: [
      Visitor(
        func: (n) => n.isIncluded = true,
        struct: (n) {
          n.isIncluded = true;
          // C tags such as `_FS_QUADPOINTSF` would become library-private Dart
          // classes; drop the leading underscore so they are usable.
          if (n.name.startsWith('_')) n.name = n.name.substring(1);
        },
        union: (n) => n.isIncluded = true,
        // C enums are int-sized on every ABI we target (Android, Linux,
        // Windows; arm64/arm/x86_64), so ffigen's size guess is safe here.
        enumClass: (n) {
          n.isIncluded = true;
          n.silenceWarning = true;
        },
        global: (n) => n.isIncluded = true,
        macroConstant: (n) => n.isIncluded = true,
        unnamedEnumConstant: (n) => n.isIncluded = true,
      ),
    ],
  );
  await generator.generate();
}
